        const request = {
            ...baseRequest,
            page,
            "page-size": pageSize,
        } as TRequest;

        // Audited 2026-05-25 (re-counted 2026-06-21): 18 of the 21
        // paginated Clockify list endpoints emit a `Last-Page: true|false`
        // response header
